def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Repair each red (2) diamond/plus from its aligned top and bottom tips.
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]
    if pts:
        rs=[r for r,c in pts]
        top,bottom=min(rs),max(rs)
        topcs=[c for r,c in pts if r==top]
        botcs=[c for r,c in pts if r==bottom]
        if len(topcs)==len(botcs)==1 and topcs[0]==botcs[0] and bottom-top==4:
            cr=(top+bottom)//2; cc=topcs[0]
            for r,c in pts: out[r][c]=7
            for r,c in [(top,cc),(cr,cc-1),(cr,cc),(cr,cc+1),(bottom,cc)]:
                if 0<=r<h and 0<=c<w: out[r][c]=2
    # Enlarge complete gray (5) diamonds by one diamond radius.
    for r in range(h):
        for c in range(w):
            plus={(r,c),(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
            if all(0<=rr<h and 0<=cc<w and grid[rr][cc]==5 for rr,cc in plus):
                for dr in range(-2,3):
                    for dc in range(-2,3):
                        if abs(dr)+abs(dc) in (0,2):
                            rr,cc=r+dr,c+dc
                            if 0<=rr<h and 0<=cc<w: out[rr][cc]=5
    # A lone gray pixel is the degenerate case: grow it into a small plus.
    p5=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==5]
    if len(p5)==1:
        r,c=p5[0]
        for rr,cc in [(r,c),(r,c-1),(r,c+1),(r+1,c)]:
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=5
    return out

